<?php $e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8'); $t=fn($k)=>$this->objLanguage->languageText('mod_registration_service_'.$k,'registration-service'); $action=$e(html_entity_decode($this->uri(array('action'=>'resetpassword'),'registration-service'),ENT_QUOTES,'UTF-8')); ?>
<main class="chisimba-workspace registration-service" aria-labelledby="reset-title"><h1 id="reset-title"><?php echo $e($t('reset_title')); ?></h1><?php if(!empty($recoveryResetError)): ?><div class="error" role="alert"><?php echo $e($t('error_'.$recoveryResetError)); ?></div><?php endif; ?><form method="post" action="<?php echo $action; ?>"><input type="hidden" name="csrf_token" value="<?php echo $e($recoveryResetCsrf??''); ?>"><input type="hidden" name="token" value="<?php echo $e($recoveryToken??''); ?>"><section class="chisimba-form-section"><div><label for="reset-password"><?php echo $e($t('new_password')); ?></label><input id="reset-password" name="password" type="password" autocomplete="new-password" required></div><div><label for="reset-password-confirm"><?php echo $e($t('password_confirm')); ?></label><input id="reset-password-confirm" name="password_confirm" type="password" autocomplete="new-password" required></div></section><div class="chisimba-form-actions"><button class="button" type="submit"><?php echo $e($t('reset_password')); ?></button></div></form></main>
